
public class PenDistributes {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int totalpens=14;
		int student=3;
		int pensperStudent =  totalpens/student;
		int remainingpens = totalpens % student;
		System.out.println("Pens per Student get " + pensperStudent + " and the remaining pens that are not distributed " + remainingpens);

	}

}

